/**
 * Recorded replay sequences: continuous 50 Hz streams rebuilt from consecutive,
 * 50%-overlapping windows of UCI HAR **held-out test subjects** (never used for training).
 * Generated by ml/har/train_har.py.
 */
import replayJson from '../../assets/replay/har_replay.json';
import { ACTIVITY_LABELS, type ActivityClass } from '@/types/domain';

interface RawSequence {
  id: string;
  subject: number;
  label: ActivityClass;
  windowIndices: number[];
  sampleRateHz: number;
  channels: string[];
  samples: number[][]; // 6 x N
}

export interface ReplayProgram {
  id: string;
  title: string;
  description: string;
  /** 6 x N samples. */
  samples: number[][];
  /** True (recorded) label for every sample index. */
  labels: ActivityClass[];
  sampleRateHz: number;
}

const DATA = replayJson as unknown as { source: string; license: string; sequences: RawSequence[] };

export const REPLAY_SOURCE = DATA.source;

function concat(seqs: RawSequence[]): { samples: number[][]; labels: ActivityClass[] } {
  const samples: number[][] = [[], [], [], [], [], []];
  const labels: ActivityClass[] = [];
  for (const s of seqs) {
    for (let c = 0; c < 6; c++) samples[c].push(...s.samples[c]);
    for (let i = 0; i < s.samples[0].length; i++) labels.push(s.label);
  }
  return { samples, labels };
}

function build(): ReplayProgram[] {
  const programs: ReplayProgram[] = [];
  const subjects = [...new Set(DATA.sequences.map((s) => s.subject))];
  const order: ActivityClass[] = ['STANDING', 'WALKING', 'WALKING_UPSTAIRS', 'WALKING_DOWNSTAIRS', 'SITTING', 'LAYING'];
  for (const subject of subjects) {
    const seqs = order
      .map((l) => DATA.sequences.find((s) => s.subject === subject && s.label === l))
      .filter((s): s is RawSequence => !!s);
    const { samples, labels } = concat(seqs);
    programs.push({
      id: `tour-${subject}`,
      title: `Full tour · subject ${subject}`,
      description: 'All six activities back-to-back, including the transitions between them.',
      samples,
      labels,
      sampleRateHz: 50,
    });
  }
  for (const s of DATA.sequences) {
    programs.push({
      id: s.id,
      title: `${ACTIVITY_LABELS[s.label]} · subject ${s.subject}`,
      description: `${(s.samples[0].length / s.sampleRateHz).toFixed(1)} s recorded clip`,
      samples: s.samples,
      labels: new Array<ActivityClass>(s.samples[0].length).fill(s.label),
      sampleRateHz: s.sampleRateHz,
    });
  }
  return programs;
}

export const REPLAY_PROGRAMS: ReplayProgram[] = build();

export function getReplayProgram(id: string): ReplayProgram | undefined {
  return REPLAY_PROGRAMS.find((p) => p.id === id);
}
